{"implementation": "def solve(case):
    initial_state = case['initial_state']
    max_steps = case['max_steps']
    tool_obs = case['tool_observations']
    transitions = case['transitions']
    trace = []
    state = initial_state
    for step in range(max_steps):
        if state not in transitions:
            return {"final": None, "status": "missing_state", "trace": trace}
        state_def = transitions[state]
        kind = state_def['kind']
        if kind == 'final':
            return {"final": state_def['value'], "status": "completed", "trace": trace}
        elif kind == 'action':
            action_name = state_def['action']
            if action_name in tool_obs:
                observation = tool_obs[action_name]
            else:
                observation = "invalid_action"
            next_by_obs = state_def.get('next_by_observation', {})
            if observation in next_by_obs:
                next_state = next_by_obs[observation]
            else:
                next_state = state_def['default_next']
            trace.append({
                "step": step,
                "state": state,
                "action": action_name,
                "observation": observation
            })
            state = next_state
        else:
            return {"final": None, "status": "invalid_state", "trace": trace}
    return {"final": None, "status": "max_steps_exceeded", "trace": trace}"}
